// Query current minimum severity and assert it is within the documented enum range [0,4].
// Also store it in global attributes for potential cross-stub coordination.
tflite::LogSeverity cur = tflite::LoggerOptions::GetMinimumLogSeverity();
int sev_int = static_cast<int>(cur);
FUZZ_ASSERT(sev_int >= static_cast<int>(tflite::TFLITE_LOG_VERBOSE) && sev_int <= static_cast<int>(tflite::TFLITE_LOG_SILENT), "LoggerOptions::GetMinimumLogSeverity out of range");
FUZZ_SET_ATTR_INT_GLOBAL("tflite_min_sev", sev_int);
// Validation: stub performs range assertion and records global state; no inputs/outputs are required for a static getter.

// Generate a valid enum value in [TFLITE_LOG_VERBOSE, TFLITE_LOG_SILENT].
unsigned int r = *FUZZ_PARAM(unsigned int);
tflite::LogSeverity new_sev = static_cast<tflite::LogSeverity>(r % 5);
// Call the API, check both old and new are valid, and persist global attribute.
tflite::LogSeverity old_sev = tflite::LoggerOptions::SetMinimumLogSeverity(new_sev);
int old_i = static_cast<int>(old_sev);
int new_i = static_cast<int>(new_sev);
FUZZ_ASSERT(new_i >= static_cast<int>(tflite::TFLITE_LOG_VERBOSE) && new_i <= static_cast<int>(tflite::TFLITE_LOG_SILENT), "SetMinimumLogSeverity new out of range");
FUZZ_ASSERT(old_i >= static_cast<int>(tflite::TFLITE_LOG_VERBOSE) && old_i <= static_cast<int>(tflite::TFLITE_LOG_SILENT), "SetMinimumLogSeverity old out of range");
FUZZ_SET_ATTR_INT_GLOBAL("tflite_min_sev", new_i);
// Optionally restore previous severity to bound global side effects and exercise the API twice.
(void)tflite::LoggerOptions::SetMinimumLogSeverity(old_sev);
FUZZ_SET_ATTR_INT_GLOBAL("tflite_min_sev", old_i);
// Validation: ensures valid enum domain, updates global attribute, and restores prior state; no persistent objects to output.

// Select a valid severity and one of several safe printf-style formats.
unsigned int rsev = *FUZZ_PARAM(unsigned int);
tflite::LogSeverity sev = static_cast<tflite::LogSeverity>(rsev % 5);
FUZZ_ASSERT(static_cast<int>(sev) >= static_cast<int>(tflite::TFLITE_LOG_VERBOSE) && static_cast<int>(sev) <= static_cast<int>(tflite::TFLITE_LOG_SILENT), "severity out of range");

unsigned int which = *FUZZ_PARAM(unsigned int) % 4;
if (which == 0) {
  // Single string.
  const char* fmt = "%s";
  std::string s = FUZZ_PARAM_STR();
  tflite::logging_internal::MinimalLogger::Log(sev, fmt, s.c_str());
} else if (which == 1) {
  // String + int.
  const char* fmt = "%s %d";
  std::string s = FUZZ_PARAM_STR();
  int v = static_cast<int>(*FUZZ_PARAM(unsigned int));
  tflite::logging_internal::MinimalLogger::Log(sev, fmt, s.c_str(), v);
} else if (which == 2) {
  // Pointer + size + string.
  const char* fmt = "%p %zu %s";
  std::string s = FUZZ_PARAM_STR();
  void* p = (void*)s.data();
  size_t n = s.size();
  tflite::logging_internal::MinimalLogger::Log(sev, fmt, p, n, s.c_str());
} else {
  // Mixed numeric forms to exercise formatting paths.
  const char* fmt = "val=%08x hex=%#llx msg=%s";
  unsigned int u = *FUZZ_PARAM(unsigned int);
  unsigned long long ull = ((unsigned long long)*FUZZ_PARAM(unsigned int) << 32) ^ (unsigned long long)*FUZZ_PARAM(unsigned int);
  std::string s = FUZZ_PARAM_STR();
  tflite::logging_internal::MinimalLogger::Log(sev, fmt, u, ull, s.c_str());
}
